insert:
if noRacials() { // wow-forever patch: WOW_FOREVER_NO_RACIALS=1 (patches/forever/sim/core/no_racials.go)
	return
}

with:
// wow-forever patch: 10% of Intellect a rank as spell damage (client 70425's tooltip and Blizzard's 16 Oct notes; user decision
// 2026-10-18). The official spell store's curve for 1311084 reads 20/40/60%, which a 70450 hotfix may have restored (audit 2 row 2).
paladin.AddStatDependency(stats.Intellect, stats.SpellDamage, 0.10*float64(paladin.Talents.ChampionOfTheLight))

if foreverPetNormalize() { // wow-forever patch: Forever keeps a faster pet's swing damage whole (patches/forever/sim/hunter/forever_pet_rule.go)
	hp.AutoAttacks.MHConfig().DamageMultiplier /= 1 + attackSpeed.Effect(dbcenums.A_MOD_ATTACKSPEED, 0).Percent()
}
